ImportResult ImportRunner::run( std::streamoff start_offset )
{
    ImportResult result;
    result.start_offset = start_offset;
    result.end_offset   = start_offset;

    CSVUtil csv( m_file );

    if( !csv ) {
        result.ok = false;
        return result;
    }

    // everything up to the last complete line ('\n') may be imported
    const std::streamoff end = complete_file_size( m_file );

    std::vector<DataRecord> batch;
    batch.reserve( m_batch_size );

    for( CSVUtil::iterator it( &csv, std::fstream::pos_type( start_offset ) );
         it != csv.end(); ++it ) {
        const std::vector<std::string> fields = *it;
        const std::streamoff pos = (std::streamoff)csv.getCurrentPos();

        if( pos >= end ) {
            break;      // trailing partial record, still being written
        }

        ++result.lines;

        if( fields.empty() ) {
            ++result.empty;
            continue;
        }

        if( fields.size() < DataRecord::MAX_FIELDS ) {
            ++result.malformed;
            continue;
        }

        DataRecord rec( fields );

        if( rec.timestamp == 0 ) {
            ++result.malformed;
            continue;
        }

        batch.push_back( rec );

        if( batch.size() >= m_batch_size ) {
            if( !m_sink.store( batch ) ) {
                result.ok = false;
                return result;
            }
            result.records += batch.size();
            batch.clear();
        }
    }

    if( !m_sink.store( batch ) ) {
        result.ok = false;
        return result;
    }

    result.records += batch.size();
    result.end_offset = end > start_offset ? end : start_offset;
    return result;
}
